def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(s: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("INT", int(s[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and "A" <= s[j] <= "Z":
                    j += 1
                if j < n and s[j].isdigit():
                    k = j + 1
                    while k < n and s[k].isdigit():
                        k += 1
                    tokens.append(("CELL", s[i:k]))
                    i = k
                else:
                    tokens.append(("FUNC", s[i:j]))
                    i = j
            elif ch in "<>":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(("OP", s[i : i + 2]))
                    i += 2
                elif ch == "<" and i + 1 < n and s[i + 1] == ">":
                    tokens.append(("OP", "<>"))
                    i += 2
                else:
                    tokens.append(("OP", ch))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        return tokens

    def parse(s: str) -> tuple:
        tokens = tokenize(s)
        pos = 0
        n = len(tokens)

        def parse_expr() -> tuple:
            nonlocal pos
            node = parse_term()
            while pos < n and tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = ("binop", op, node, right)
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while pos < n and tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ("binop", op, node, right)
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            if pos < n and tokens[pos][0] == "-":
                pos += 1
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom() -> tuple:
            nonlocal pos
            tok_type, tok_val = tokens[pos]
            if tok_type == "INT":
                pos += 1
                return ("num", tok_val)
            if tok_type == "CELL":
                pos += 1
                return ("cell", tok_val)
            if tok_type == "(":
                pos += 1
                node = parse_expr()
                pos += 1
                return node
            func = tok_val
            pos += 2
            if func == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1
                then_node = parse_expr()
                pos += 1
                else_node = parse_expr()
                pos += 1
                return ("if", op, left, right, then_node, else_node)
            args = []
            while True:
                if (
                    pos + 1 < n
                    and tokens[pos][0] == "CELL"
                    and tokens[pos + 1][0] == ":"
                ):
                    c1_name = tokens[pos][1]
                    c2_name = tokens[pos + 2][1]
                    pos += 3
                    col1, row1 = ord(c1_name[0]), int(c1_name[1:])
                    col2, row2 = ord(c2_name[0]), int(c2_name[1:])
                    if col1 > col2:
                        col1, col2 = col2, col1
                    if row1 > row2:
                        row1, row2 = row2, row1
                    args.append(("range", row1, row2, col1, col2))
                else:
                    args.append(parse_expr())
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    pos += 1
                    break
            return ("agg", func, args)

        return parse_expr()

    results: dict[str, int | str] = {}
    asts: dict[str, tuple] = {}
    for name, content in cells.items():
        if content.startswith("="):
            asts[name] = parse(content[1:])
        else:
            results[name] = int(content)

    in_progress: set[str] = set()

    for root in cells:
        if root in results:
            continue
        stack: list[tuple] = []
        task: tuple = ("eval_cell", root)

        while True:
            kind = task[0]
            if kind == "eval_cell":
                name = task[1]
                if name not in cells:
                    task = ("return", 0)
                elif name in results:
                    task = ("return", results[name])
                elif name in in_progress:
                    task = ("return", "#CYCLE!")
                else:
                    in_progress.add(name)
                    stack.append(("cell", name))
                    task = ("eval_node", asts[name])
            elif kind == "eval_node":
                node = task[1]
                nk = node[0]
                if nk == "num":
                    task = ("return", node[1])
                elif nk == "cell":
                    task = ("eval_cell", node[1])
                elif nk == "neg":
                    stack.append(("neg",))
                    task = ("eval_node", node[1])
                elif nk == "binop":
                    stack.append(("binop_left", node[1], node[3]))
                    task = ("eval_node", node[2])
                elif nk == "if":
                    stack.append(("if_left", node[1], node[3], node[4], node[5]))
                    task = ("eval_node", node[2])
                else:
                    task = ("agg_step", node[1], node[2], 0, 0, 0, 0, False)
            elif kind == "agg_step":
                _, func, args, idx, r, c, acc, has_val = task
                n_args = len(args)
                dispatched = False
                while idx < n_args:
                    arg = args[idx]
                    if arg[0] == "range":
                        _, r1, r2, c1, c2 = arg
                        if r == 0:
                            r, c = r1, c1
                        while r <= r2:
                            cname = f"{chr(c)}{r}"
                            nc = c + 1
                            nr = r
                            if nc > c2:
                                nc = c1
                                nr += 1
                            if cname in cells:
                                if nr > r2:
                                    stack.append(("agg", func, args, idx + 1, 0, 0, acc, has_val))
                                else:
                                    stack.append(("agg", func, args, idx, nr, nc, acc, has_val))
                                task = ("eval_cell", cname)
                                dispatched = True
                                break
                            r, c = nr, nc
                        if dispatched:
                            break
                        idx += 1
                        r = 0
                    else:
                        stack.append(("agg", func, args, idx + 1, 0, 0, acc, has_val))
                        task = ("eval_node", arg)
                        dispatched = True
                        break
                if not dispatched:
                    task = ("return", acc if has_val else 0)
            else:
                res = task[1]
                if not stack:
                    break
                frame = stack.pop()
                fk = frame[0]
                if fk == "cell":
                    cname = frame[1]
                    in_progress.remove(cname)
                    results[cname] = res
                    task = ("return", res)
                elif fk == "neg":
                    if isinstance(res, str):
                        task = ("return", res)
                    else:
                        task = ("return", -res)
                elif fk == "binop_left":
                    if isinstance(res, str):
                        task = ("return", res)
                    else:
                        stack.append(("binop_right", frame[1], res))
                        task = ("eval_node", frame[2])
                elif fk == "binop_right":
                    if isinstance(res, str):
                        task = ("return", res)
                    else:
                        op, left_val = frame[1], frame[2]
                        if op == "+":
                            val: int | str = left_val + res
                        elif op == "-":
                            val = left_val - res
                        elif op == "*":
                            val = left_val * res
                        else:
                            if res == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(left_val) // abs(res)
                                val = -q if (left_val < 0) ^ (res < 0) else q
                        task = ("return", val)
                elif fk == "if_left":
                    if isinstance(res, str):
                        task = ("return", res)
                    else:
                        stack.append(("if_right", frame[1], res, frame[3], frame[4]))
                        task = ("eval_node", frame[2])
                elif fk == "if_right":
                    if isinstance(res, str):
                        task = ("return", res)
                    else:
                        op, left_val, then_node, else_node = frame[1], frame[2], frame[3], frame[4]
                        if op == "=":
                            cond = left_val == res
                        elif op == "<>":
                            cond = left_val != res
                        elif op == "<":
                            cond = left_val < res
                        elif op == "<=":
                            cond = left_val <= res
                        elif op == ">":
                            cond = left_val > res
                        else:
                            cond = left_val >= res
                        task = ("eval_node", then_node if cond else else_node)
                else:
                    _, func, args, idx, r, c, acc, has_val = frame
                    if isinstance(res, str):
                        task = ("return", res)
                    else:
                        if not has_val:
                            acc = res
                            has_val = True
                        elif func == "SUM":
                            acc += res
                        elif func == "MIN":
                            if res < acc:
                                acc = res
                        else:
                            if res > acc:
                                acc = res
                        task = ("agg_step", func, args, idx, r, c, acc, has_val)

    return results
